function compute(s) {
  var n = Math.max(1, Math.min(6, Math.round(s.n)));
  var raw = (s.p || []).slice(0, n);
  while (raw.length < n) raw.push(0);
  raw = raw.map(function (v) { return Math.max(0, Number(v) || 0); });
  var sum = PG.sum(raw);
  var p;
  if (sum <= 0) {
    p = raw.map(function () { return 1 / n; });
  } else {
    p = raw.map(function (v) { return v / sum; });
  }
  if (s.uniform) {
    p = p.map(function () { return 1 / n; });
  }
  var terms = p.map(function (pi) {
    if (pi <= 0) return 0;
    return -pi * PG.log2(pi);
  });
  var H = PG.sum(terms);
  var maxH = PG.log2(n);
  var uniformP = 1 / n;
  var twoP = p.length > 0 ? p[0] : 0;
  var twoH = 0;
  if (twoP > 0) twoH += -twoP * PG.log2(twoP);
  var q = 1 - twoP;
  if (q > 0) twoH += -q * PG.log2(q);
  var twoOn = s.two === "on";
  return {
    n: n,
    p: p,
    terms: terms,
    H: H,
    maxH: maxH,
    deficit: maxH - H,
    uniformP: uniformP,
    twoP: twoP,
    twoH: twoH,
    twoOn: twoOn ? 1 : 0,
    sum: PG.sum(p)
  };
}

function render(s, r) {
  var w = 760, h = 420;
  var body = "";
  var n = r.n;
  var colors = [];
  for (var i = 0; i < n; i++) colors.push(PG.color(i));

  // Left panel: probabilities
  var lx = 40, ly = 60, lw = 320, lh = 280;
  body += PG.text(lx, ly - 24, "Probabilities $p_i$", { size: 15, weight: "bold" });
  var pVals = r.p;
  var pLabels = [];
  for (var j = 0; j < n; j++) pLabels.push("$p_{" + (j + 1) + "}$");
  body += PG.bars({
    x: lx, y: ly, w: lw, h: lh,
    values: pVals, labels: pLabels,
    title: "", yLabel: "probability",
    min: 0, max: 1,
    colors: colors,
    fmt: function (v) { return PG.fmt(v, 2); },
    refLines: [{ value: r.uniformP, label: "1/n = " + PG.fmt(r.uniformP, 2) }]
  });

  // Right panel: contributions
  var rx = 420, ry = 60, rw = 300, rh = 280;
  body += PG.text(rx, ry - 24, "Contributions $-p_i\\log_2 p_i$", { size: 15, weight: "bold" });
  var cVals = r.terms;
  var cLabels = [];
  for (var k = 0; k < n; k++) cLabels.push("$c_{" + (k + 1) + "}$");
  var cMax = Math.max(0.5, r.maxH);
  body += PG.bars({
    x: rx, y: ry, w: rw, h: rh,
    values: cVals, labels: cLabels,
    title: "", yLabel: "bits",
    min: 0, max: cMax,
    colors: colors,
    fmt: function (v) { return PG.fmt(v, 3); },
    refLines: [{ value: r.maxH, label: "log2 n = " + PG.fmt(r.maxH, 2) }]
  });

  // Total entropy bar
  var tx = 40, ty = 370, tw = 680, th = 22;
  body += PG.text(tx, ty - 8, "Total entropy H = " + PG.fmt(r.H, 3) + " bits", { size: 14, weight: "bold" });
  var frac = r.maxH > 0 ? PG.clamp(r.H / r.maxH, 0, 1) : 0;
  body += PG.rect(tx, ty, tw, th, { fill: "#e8e8e8", stroke: "#999", rx: 4 });
  body += PG.rect(tx, ty, tw * frac, th, { fill: PG.color(0), rx: 4 });
  body += PG.text(tx + tw + 6, ty + th / 2, PG.fmt(r.H, 3), { size: 13, anchor: "start", baseline: "middle" });

  // Two-outcome overlay when enabled
  if (r.twoOn) {
    var ox = 40, oy = 300, ow = 680, oh = 60;
    body += PG.text(ox, oy - 6, "Two-outcome view: H(p, 1-p) with p = " + PG.fmt(r.twoP, 3) + " -> " + PG.fmt(r.twoH, 3) + " bits", { size: 13, weight: "bold" });
    var pts = [];
    for (var t = 0; t <= 40; t++) {
      var pp = t / 40;
      var hh = 0;
      if (pp > 0) hh += -pp * PG.log2(pp);
      if (1 - pp > 0) hh += -(1 - pp) * PG.log2(1 - pp);
      pts.push([ox + pp * ow, oy + oh - (hh / 1) * oh]);
    }
    body += PG.plot({
      x: ox, y: oy, w: ow, h: oh,
      series: [{ points: pts, label: "H(p,1-p)", color: PG.color(2) }],
      xDomain: [0, 1], yDomain: [0, 1],
      xLabel: "p", yLabel: "bits",
      markers: [{ x: r.twoP, y: r.twoH, label: "current", color: PG.color(0) }]
    });
  }

  return PG.svg(w, h, body);
}

function show(s, r) {
  var rows = [];
  rows.push({ label: "Number of outcomes $n$", value: r.n, digits: 0 });
  rows.push({ label: "Probabilities $p_i$", value: r.p, digits: 3, colLabels: r.p.map(function (_, i) { return "$p_{" + (i + 1) + "}$"; }) });
  rows.push({ label: "Contributions $-p_i\\log_2 p_i$", value: r.terms, digits: 4, colLabels: r.terms.map(function (_, i) { return "$c_{" + (i + 1) + "}$"; }) });
  rows.push({ label: "Total entropy $H$ (bits)", value: r.H, digits: 4, highlight: true });
  rows.push({ label: "Maximum $\\log_2 n$ (bits)", value: r.maxH, digits: 4 });
  rows.push({ label: "Deficit $\\log_2 n - H$", value: r.deficit, digits: 4 });
  rows.push({ label: "Two-outcome $H(p, 1-p)$ (bits)", value: r.twoH, digits: 4 });
  rows.push({ label: "Two-outcome view active", value: r.twoOn ? "on" : "off" });
  return rows;
}

function checks(s, r) {
  var out = [];
  var n = r.n;

  // Certainty gives zero bits
  var certain = { n: n, p: [], uniform: false, two: "off" };
  for (var i = 0; i < n; i++) certain.p.push(i === 0 ? 1 : 0);
  var rc = compute(certain);
  out.push({
    name: "Certainty gives 0 bits",
    pass: Math.abs(rc.H) < 1e-9,
    detail: "With p = (1,0,...,0), H = " + PG.fmt(rc.H, 6) + " bits."
  });

  // Four equally likely outcomes give 2 bits
  var four = { n: 4, p: [0.25, 0.25, 0.25, 0.25], uniform: false, two: "off" };
  var r4 = compute(four);
  out.push({
    name: "Four equally likely outcomes give 2 bits",
    pass: Math.abs(r4.H - 2) < 1e-9,
    detail: "With p = (0.25,0.25,0.25,0.25), H = " + PG.fmt(r4.H, 6) + " bits."
  });

  // H >= 0
  out.push({
    name: "H is nonnegative",
    pass: r.H >= -1e-9,
    detail: "H = " + PG.fmt(r.H, 6) + " bits."
  });

  // H <= log2 n
  out.push({
    name: "H never exceeds log2 n",
    pass: r.H <= r.maxH + 1e-9,
    detail: "H = " + PG.fmt(r.H, 6) + " <= log2 n = " + PG.fmt(r.maxH, 6) + "."
  });

  // Zero probabilities contribute zero
  var zeroOk = true;
  for (var k = 0; k < r.p.length; k++) {
    if (r.p[k] === 0 && Math.abs(r.terms[k]) > 1e-12) zeroOk = false;
  }
  out.push({
    name: "Zero probabilities contribute 0",
    pass: zeroOk,
    detail: "Every p_i = 0 has contribution -p_i log2 p_i = 0."
  });

  // Uniform maximizes H
  var uni = { n: n, p: [], uniform: true, two: "off" };
  for (var m = 0; m < n; m++) uni.p.push(1 / n);
  var ru = compute(uni);
  out.push({
    name: "Uniform distribution maximizes H",
    pass: ru.H >= r.H - 1e-9 && Math.abs(ru.H - r.maxH) < 1e-9,
    detail: "Uniform H = " + PG.fmt(ru.H, 6) + " >= current H = " + PG.fmt(r.H, 6) + "."
  });

  // Two-outcome view consistency
  var twoOn = compute({ n: n, p: r.p, uniform: s.uniform, two: "on" });
  var twoOff = compute({ n: n, p: r.p, uniform: s.uniform, two: "off" });
  out.push({
    name: "Two-outcome toggle changes the view",
    pass: twoOn.twoOn !== twoOff.twoOn,
    detail: "twoOn flag = " + twoOn.twoOn + " vs " + twoOff.twoOn + "."
  });

  return out;
}
